<script lang="ts">
 import HelpTooltip from '$lib/components/HelpTooltip.svelte';
 import { api } from '$lib/api';import { t } from '$lib/i18n';import { Button } from '$lib/components/ui/button';import { Input } from '$lib/components/ui/input';import { Label } from '$lib/components/ui/label';import { signInWithPasskey } from '$lib/native-auth';
 let password=$state(''),code=$state(''),busy=$state(false),error=$state(''),verified=$state(false);
 async function verify(passkey=false){busy=true;error='';try{if(passkey)await signInWithPasskey(true);else await api.post('/v1/auth/reauthenticate',{password,code});password='';code='';verified=true;}catch(e){error=e instanceof Error?e.message:$t('nativeAuth.failed');}finally{busy=false;}}
</script>
<div class="space-y-3 rounded-lg border bg-muted/20 p-3"><div class="flex items-center gap-1"><span class="text-xs font-medium">{$t('nativeAuth.verifyTitle')}</span><HelpTooltip label={$t('nativeAuth.verifyTitle')} text={$t('nativeAuth.verifyHint')} /></div><div class="space-y-1.5"><Label for="verify-password">{$t('securitySettings.currentPassword')}</Label><Input id="verify-password" type="password" autocomplete="current-password" bind:value={password} /></div><div class="space-y-1.5"><Label for="verify-code">{$t('nativeAuth.code')}</Label><Input id="verify-code" autocomplete="one-time-code" bind:value={code} /></div><div class="flex flex-wrap gap-2"><Button type="button" size="sm" variant="outline" disabled={busy} onclick={()=>verify()}>{$t('nativeAuth.verify')}</Button><Button type="button" size="sm" variant="outline" disabled={busy} onclick={()=>verify(true)}>{$t('nativeAuth.usePasskey')}</Button></div>{#if verified}<p class="text-xs text-muted-foreground" role="status">{$t('nativeAuth.verified')}</p>{/if}{#if error}<p role="alert" class="text-sm text-destructive">{error}</p>{/if}</div>
